package support

import (
	"fmt"
	"os"
	"path/filepath"
	"runtime"

	"github.com/joho/godotenv"
)

// ProjectRoot returns the weather-insurance repo root (parent of tools/).
func ProjectRoot() string {
	_, file, _, ok := runtime.Caller(0)
	if !ok {
		return ""
	}
	return filepath.Clean(filepath.Join(filepath.Dir(file), "..", "..", ".."))
}

// LoadProjectEnv loads .env from the repo root, then config/extension.env
// (auto-generated by pre-build.sh). extension.env overrides on conflict.
func LoadProjectEnv() {
	root := ProjectRoot()
	if root == "" {
		_ = godotenv.Load()
		return
	}
	envPath := filepath.Join(root, ".env")
	if err := godotenv.Load(envPath); err != nil && !os.IsNotExist(err) {
		_, _ = fmt.Fprintf(os.Stderr, "Warning: Error loading .env: %v\n", err)
	}
	extPath := filepath.Join(root, "config", "extension.env")
	if err := godotenv.Overload(extPath); err != nil && !os.IsNotExist(err) {
		_, _ = fmt.Fprintf(os.Stderr, "Warning: Error loading extension.env: %v\n", err)
	}
}
